import json
d=json.load(open('gestures.json'))
def walk(n,out):
    if isinstance(n,dict):
        t=n.get('type')
        if t=='text': out.append(n.get('text',''))
        elif t=='codeVoice': out.append('\`'+n.get('code','')+'\`')
        elif t in ('paragraph','heading','listItem','item'):
            for k in ('inlineContent','content','items'):
                if k in n: walk(n[k],out)
            out.append('\n')
        elif t=='reference': out.append(n.get('title') or '')
        else:
            for k,v in n.items():
                if isinstance(v,(list,dict)): walk(v,out)
        if t=='heading': out.insert(len(out)-1,'\n## ')
    elif isinstance(n,list):
        for i in n: walk(i,out)
o=[]
walk(d.get('primaryContentSections',[]),o)
